// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    address public owner = address(this);

    function setUp() public { c = new Phishable(owner); }

    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != owner);
        vm.assume(nonOwner != address(0));

        vm.deal(nonOwner, 1 ether);
        vm.prank(nonOwner);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "funding failed");

        vm.prank(nonOwner);
        bool ok;
        try c.withdrawAll(nonOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
